import json
from itertools import permutations

def solve_puzzle():
    houses = [0, 1, 2, 3]  # 0-based indices for houses 1..4

    names = ["Eric", "Peter", "Alice", "Arnold"]
    cars = ["tesla model 3", "honda civic", "toyota camry", "ford f150"]
    months = ["jan", "april", "sept", "feb"]
    hobbies = ["painting", "cooking", "gardening", "photography"]

    def inv(lst):
        return {lst[i]: i for i in range(len(lst))}

    solution_rows = None

    for name_at in permutations(names):
        pos_name = inv(name_at)

        for month_at in permutations(months):
            # 1. The person whose birthday is in January is not in the second house.
            if month_at[1] == "jan":
                continue
            # 11. Peter is the person whose birthday is in January.
            if month_at[pos_name["Peter"]] != "jan":
                continue
            # 9. The person whose birthday is in April is Arnold.
            if month_at[pos_name["Arnold"]] != "april":
                continue

            for car_at in permutations(cars):
                # 6. The person who owns a Tesla Model 3 is Arnold.
                if car_at[pos_name["Arnold"]] != "tesla model 3":
                    continue
                # 8. The person who owns a Toyota Camry is Peter.
                if car_at[pos_name["Peter"]] != "toyota camry":
                    continue
                # 4. The person who owns a Honda Civic is directly left of the person who owns a Tesla Model 3.
                pos_tesla = car_at.index("tesla model 3")
                pos_honda = car_at.index("honda civic")
                if pos_honda + 1 != pos_tesla:
                    continue

                for hobby_at in permutations(hobbies):
                    # 10. Alice is the photography enthusiast.
                    if hobby_at[pos_name["Alice"]] != "photography":
                        continue
                    pos_photo = hobby_at.index("photography")
                    # 2. The photography enthusiast is somewhere to the left of Eric.
                    if not (pos_photo < pos_name["Eric"]):
                        continue
                    # 3. The photography enthusiast is somewhere to the left of Peter.
                    if not (pos_photo < pos_name["Peter"]):
                        continue
                    # 7. The person whose birthday is in February is the person who loves cooking.
                    if month_at.index("feb") != hobby_at.index("cooking"):
                        continue
                    # 5. There is one house between the person who owns a Tesla Model 3 and the person who enjoys gardening.
                    if abs(pos_tesla - hobby_at.index("gardening")) != 2:
                        continue

                    # If all constraints satisfied, we have a solution
                    rows = []
                    for i in houses:
                        rows.append([str(i + 1), name_at[i], car_at[i], month_at[i], hobby_at[i]])
                    solution_rows = rows
                    break
                if solution_rows:
                    break
            if solution_rows:
                break
        if solution_rows:
            break

    if not solution_rows:
        raise RuntimeError("No solution found")

    return {
        "solution": {
            "header": ["House", "Name", "CarModel", "Birthday", "Hobby"],
            "rows": solution_rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
